// Generated by cmake/embed.cmake from third_party/tabler-icons.
// NOLINTBEGIN(*-avoid-c-arrays,readability-identifier-naming): the generated arrays
namespace rummage::embedded {
extern const unsigned char tabler_icons[];
extern const std::size_t tabler_icons_size;
extern const unsigned char tabler_icons_filled[];
extern const std::size_t tabler_icons_filled_size;
}  // namespace rummage::embedded

// NOLINTEND(*-avoid-c-arrays,readability-identifier-naming)

namespace rummage::ui {
namespace {

constexpr std::string_view kFilled = "-filled";

std::string_view theme_name(std::string_view name) {
    static constexpr std::pair<std::string_view, std::string_view> names[]{
        {"folder", "folder"},
        {"folder-symlink", "folder"},
        {"file", "text-x-generic"},
        {"photo", "image-x-generic"},
        {"aperture", "image-x-generic"},
        {"vector", "image-svg+xml"},
        {"movie", "video-x-generic"},
        {"music", "audio-x-generic"},
        {"file-text", "text-x-generic"},
        {"file-code", "text-x-script"},
        {"markdown", "text-markdown"},
        {"file-type-pdf", "application-pdf"},
        {"file-zip", "package-x-generic"},
        {"file-description", "x-office-document"},
        {"file-spreadsheet", "x-office-spreadsheet"},
        {"presentation", "x-office-presentation"},
        {"database", "application-x-sqlite3"},
        {"typography", "font-x-generic"},
        {"disc", "media-optical"},
        {"terminal-2", "utilities-terminal"},
        {"home", "user-home"},
        {"trash", "user-trash"},
        {"trash-filled", "user-trash-full"},
        {"usb", "drive-removable-media"},
        {"device-desktop", "computer"},
        {"server", "network-server"},
        {"download", "folder-download"},
        {"mail", "internet-mail"},
        {"calendar", "x-office-calendar"},
        {"app-window", "application-x-desktop"},
        {"plug", "drive-harddisk"},
    };
    for (const auto& [tabler, themed] : names) {
        if (name == tabler) {
            return themed;
        }
    }
    return {};
}

}  // namespace

IconSet::IconSet(FontSystem& fonts) : fonts_{fonts} {
    outline_ = fonts_.add_font_data(std::span{embedded::tabler_icons, embedded::tabler_icons_size},
                                    "tabler-icons.ttf");
    filled_ = fonts_.add_font_data(
        std::span{embedded::tabler_icons_filled, embedded::tabler_icons_filled_size},
        "tabler-icons-filled.ttf");
    if (!outline_) {
        log::warn("icons: the icon font cannot be loaded; no icons");
    }
}

IconSet::Glyph IconSet::glyph(std::string_view name) {
    std::string key{name};
    if (const auto it = glyphs_.find(key); it != glyphs_.end()) {
        return it->second;
    }
    Glyph found;
    const bool filled = name.size() > kFilled.size() && name.ends_with(kFilled);
    const std::optional<std::uint32_t> font = filled ? filled_ : outline_;
    if (font) {
        const std::string_view base = filled ? name.substr(0, name.size() - kFilled.size()) : name;
        found = {.font = *font, .index = fonts_.glyph_by_name(*font, base)};
    }
    glyphs_.emplace(std::move(key), found);
    return found;
}

bool IconSet::has(std::string_view name) { return glyph(name).index != 0; }

void IconSet::set_theme(std::string theme) {
    if (theme == "system") {
        theme = desktop_icon_theme();
    }
    if (theme != selected_theme_) {
        selected_theme_ = theme;
        pending_theme_ = std::move(theme);
    }
}

void IconSet::set_place_icons(std::map<std::string, std::string> icons) {
    if (icons != place_icons_) {
        place_icons_ = std::move(icons);
        pending_theme_ = selected_theme_;  // clear cached custom images at the next GL draw
    }
}

bool IconSet::draw_themed(Renderer& renderer, std::string_view name, float x, float y, float size,
                          Color color) {
    if (pending_theme_) {
        themed_.clear();
        theme_bytes_ = 0;
        theme_.reset();
        if (*pending_theme_ != "builtin") {
            theme_ = std::make_unique<IconTheme>(*pending_theme_, icon_theme_roots());
        }
        pending_theme_.reset();
    }
    const bool custom_file = name.starts_with('/');
    if ((!theme_ && !custom_file) || name.empty()) {
        return false;
    }
    const int pixels = std::clamp(static_cast<int>(std::ceil(size * renderer.scale())), 1, 1024);
    const std::string key = std::string{name} + ':' + std::to_string(pixels);
    auto it = themed_.find(key);
    if (it == themed_.end()) {
        // Bound textures and negative lookups without evicting a texture in the current batch.
        if (themed_.size() >= 1024 || theme_bytes_ >= 64U * 1024U * 1024U) {
            return false;
        }
        const auto file = custom_file ? std::filesystem::path{name} : theme_->find(name, pixels);
        picture::Image image;
        if (!file.empty()) {
            bool unsupported_filter = false;
            image = IconTheme::render(file, pixels, &unsupported_filter);
            // Theme lookups are bounded above; retain warning names across size/theme changes.
            if (unsupported_filter && svg_warnings_.size() < 4096 &&
                svg_warnings_.insert(file.string()).second)
                log::warn("icon {}: unsupported SVG filter primitive; rendering unfiltered",
                          file.string());
        }
        std::unique_ptr<Texture> texture;
        if (!image.empty()) {
            texture = std::make_unique<Texture>(image.width, image.height, image.rgba);
            theme_bytes_ += texture->bytes();
        }
        it = themed_.emplace(key, std::move(texture)).first;
    }
    if (!it->second) {
        return false;
    }
    const Texture& texture = *it->second;
    const float fit = size / static_cast<float>(std::max(texture.width(), texture.height()));
    const float width = static_cast<float>(texture.width()) * fit;
    const float height = static_cast<float>(texture.height()) * fit;
    renderer.draw_image(texture,
                        {x + (size - width) / 2.0F, y + (size - height) / 2.0F, width, height}, {},
                        color.a);
    return true;
}

void IconSet::draw_file(Renderer& renderer, std::string_view mime, std::string_view fallback,
                        float x, float y, float size, Color color, std::string_view preferred) {
    // Folder overrides follow the selected theme; explicit Places overrides also work with
    // builtin icons, so their custom-file support in draw_themed must not change this policy.
    if (selected_theme_ != "builtin" && !preferred.empty() &&
        draw_themed(renderer, preferred, x, y, size, color)) {
        return;
    }
    std::string name{mime};
    std::ranges::replace(name, '/', '-');
    if (!draw_themed(renderer, name, x, y, size, color)) {
        draw(renderer, fallback, x, y, size, color);
    }
}

void IconSet::draw_place(Renderer& renderer, std::string_view key, std::string_view fallback,
                         float x, float y, float size, Color color) {
    auto it = place_icons_.find(std::string{key});
    if (it == place_icons_.end() && key == "trash_full") {
        it = place_icons_.find("trash");
    }
    if (it != place_icons_.end()) {
        const std::string_view custom = it->second;
        if (custom.starts_with("builtin:")) {
            const auto name = custom.substr(8);
            if (has(name)) {
                draw_builtin(renderer, name, x, y, size, color);
                return;
            }
        } else if (draw_themed(renderer, custom, x, y, size, color)) {
            return;
        }
    }
    draw(renderer, fallback, x, y, size, color);
}

void IconSet::draw(Renderer& renderer, std::string_view name, float x, float y, float size,
                   Color color) {
    if (draw_themed(renderer, theme_name(name), x, y, size, color)) {
        return;
    }
    draw_builtin(renderer, name, x, y, size, color);
}

void IconSet::draw_builtin(Renderer& renderer, std::string_view name, float x, float y, float size,
                           Color color) {
    if (!outline_) {
        return;
    }
    const bool known = glyphs_.contains(std::string{name});
    Glyph found = glyph(name);
    if (found.index == 0) {
        if (!known) {
            log::warn("icons: no icon named '{}' (third_party/tabler-icons/icons.txt)", name);
        }
        found = glyph("file");
    }
    const TextLayout layout = fonts_.glyph_layout(found.font, found.index, size, renderer.scale());
    renderer.draw_layout(layout, x, y, color);
}

}  // namespace rummage::ui
